/* ComfyUI Template Browser
 * Static viewer for catalog/templates.json (generated by scripts/build_catalog.py).
 * No build step. marked + DOMPurify are optional (used to render Markdown notes).
 */
(() => {
  'use strict';

  // ------------------------------------------------------------------ config

  const RELAY_REPO = document.querySelector('meta[name="relay-repo"]')?.content || '';
  const DATA_URLS = ['templates.json', '../catalog/templates.json'];
  const PAGE_SIZE = 48;
  const BASE_TITLE = document.title;
  const IMG_RE = /\.(webp|png|jpe?g|gif|avif)(\?|$)/i;
  const AUDIO_RE = /\.(mp3|wav|ogg|flac|m4a)(\?|$)/i;
  const MEDIA_LABEL = { image: 'Image', video: 'Video', audio: 'Audio', '3d': '3D', llm: 'LLM', text: 'Text' };
  const MEDIA_ICON = { image: 'image', video: 'video', audio: 'audio', '3d': 'cube', llm: 'chat' };

  const ICONS = {
    logo: '<svg viewBox="0 0 24 24"><rect x="3" y="4" width="8" height="6" rx="1.5"/><rect x="13" y="14" width="8" height="6" rx="1.5"/><path d="M11 7h2.5a2 2 0 0 1 2 2v5"/></svg>',
    search: '<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>',
    x: '<svg viewBox="0 0 24 24"><path d="M18 6 6 18M6 6l12 12"/></svg>',
    sun: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/></svg>',
    moon: '<svg viewBox="0 0 24 24"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>',
    filter: '<svg viewBox="0 0 24 24"><path d="M3 5h18M6 12h12M10 19h4"/></svg>',
    download: '<svg viewBox="0 0 24 24"><path d="M12 3v12M7 10l5 5 5-5M5 21h14"/></svg>',
    copy: '<svg viewBox="0 0 24 24"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>',
    external: '<svg viewBox="0 0 24 24"><path d="M14 4h6v6M20 4 10 14M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5"/></svg>',
    book: '<svg viewBox="0 0 24 24"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5z"/><path d="M4 19.5A2.5 2.5 0 0 0 6.5 22H20v-5"/></svg>',
    file: '<svg viewBox="0 0 24 24"><path d="M14 3H6a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8z"/><path d="M14 3v5h5M8 13h8M8 17h5"/></svg>',
    chevL: '<svg viewBox="0 0 24 24"><path d="m15 18-6-6 6-6"/></svg>',
    chevR: '<svg viewBox="0 0 24 24"><path d="m9 18 6-6-6-6"/></svg>',
    image: '<svg viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-5-5L5 21"/></svg>',
    video: '<svg viewBox="0 0 24 24"><rect x="2" y="5" width="14" height="14" rx="2"/><path d="m16 10 6-3v10l-6-3"/></svg>',
    audio: '<svg viewBox="0 0 24 24"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>',
    cube: '<svg viewBox="0 0 24 24"><path d="M21 8 12 3 3 8v8l9 5 9-5z"/><path d="m3 8 9 5 9-5M12 13v8"/></svg>',
    chat: '<svg viewBox="0 0 24 24"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>',
    layers: '<svg viewBox="0 0 24 24"><path d="m12 2 10 5-10 5L2 7z"/><path d="m2 17 10 5 10-5M2 12l10 5 10-5"/></svg>',
    github: '<svg class="solid" viewBox="0 0 16 16"><path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27.68 0 1.36.09 2 .27 1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8z"/></svg>',
  };

  // ------------------------------------------------------------------ helpers

  const $ = (sel, root = document) => root.querySelector(sel);

  function h(tag, attrs, ...kids) {
    const el = document.createElement(tag);
    if (attrs) {
      for (const [k, v] of Object.entries(attrs)) {
        if (v == null || v === false) continue;
        if (k === 'class') el.className = v;
        else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2), v);
        else el.setAttribute(k, v === true ? '' : v);
      }
    }
    for (const kid of kids.flat(Infinity)) {
      if (kid == null || kid === false || kid === '') continue;
      el.append(kid instanceof Node ? kid : String(kid));
    }
    return el;
  }

  function icon(name, cls = '') {
    const s = document.createElement('span');
    s.className = 'i' + (cls ? ' ' + cls : '');
    s.setAttribute('aria-hidden', 'true');
    s.innerHTML = ICONS[name] || '';
    return s;
  }

  const safeUrl = (u) => (typeof u === 'string' && /^https?:\/\//i.test(u) ? u : null);
  const fmtNum = (n) => (typeof n === 'number' ? n.toLocaleString() : '');
  const mediaLabel = (m) => MEDIA_LABEL[m] || (m ? m[0].toUpperCase() + m.slice(1) : 'Other');
  const mediaIcon = (m) => MEDIA_ICON[m] || 'layers';

  function fmtSize(n) {
    if (!(n > 0)) return '';
    const units = ['B', 'KB', 'MB', 'GB', 'TB'];
    let i = 0;
    while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
    return (i ? n.toFixed(1) : n) + ' ' + units[i];
  }

  function fmtDate(d) {
    if (!d) return '';
    const dt = new Date(String(d).slice(0, 10) + 'T00:00:00');
    return isNaN(dt) ? d : dt.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  }

  function hostOf(u) {
    try { return new URL(u).hostname.replace(/^www\./, ''); } catch { return 'link'; }
  }

  let toastTimer;
  function toast(msg) {
    const el = $('#toast');
    const dlg = $('#detail');
    (dlg.open ? dlg : document.body).append(el);
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('show'), 3400);
  }

  // ------------------------------------------------------------------ state

  let ALL = [];
  let SOURCE = {};
  const byName = new Map();
  let current = [];
  let shown = 0;
  let lastCounts = {};
  let lastSearch = location.search;

  const FACETS = [
    { key: 'cat', label: 'Category', get: (t) => [t.category], keepOrder: true },
    { key: 'media', label: 'Output', get: (t) => [t._out], labelOf: mediaLabel },
    {
      key: 'access', label: 'Runs on', get: (t) => [t._api ? 'api' : 'oss'], values: ['oss', 'api'],
      labelOf: (v) => (v === 'api' ? 'API / cloud nodes' : 'Local (open source)'),
    },
    {
      key: 'nodes', label: 'Custom nodes', get: (t) => [t._custom ? 'custom' : 'core'], values: ['core', 'custom'],
      labelOf: (v) => (v === 'core' ? 'Core nodes only' : 'Needs custom nodes'),
    },
    { key: 'model', label: 'Model', get: (t) => t.models || [], searchable: true, limit: 10 },
    { key: 'tag', label: 'Tag', get: (t) => t.tags || [], searchable: true, limit: 10 },
  ];
  FACETS.forEach((f) => { f.labelOf = f.labelOf || ((v) => v); });

  const SORTS = [
    ['default', 'Featured'],
    ['newest', 'Newest'],
    ['popular', 'Most used'],
    ['az', 'A–Z'],
    ['size', 'Smallest download'],
  ];

  const state = {
    q: '',
    sort: 'default',
    sel: Object.fromEntries(FACETS.map((f) => [f.key, new Set()])),
    open: null,
    expanded: {},
    facetQ: {},
  };

  // ------------------------------------------------------------------ data

  async function loadData() {
    let lastErr;
    for (const url of DATA_URLS) {
      try {
        const r = await fetch(url, { cache: 'no-cache' });
        if (r.ok) return await r.json();
        lastErr = new Error(`${url}: HTTP ${r.status}`);
      } catch (e) { lastErr = e; }
    }
    throw lastErr || new Error('No data');
  }

  function prep(t, i) {
    t._i = i;
    t._title = t.title || t.name;
    t._out = t.outputType || t.mediaType || 'other';
    t._imgs = (t.thumbnails || []).filter((u) => IMG_RE.test(u));
    t._audio = (t.thumbnails || []).filter((u) => AUDIO_RE.test(u));
    t._api = t.openSource === false;
    t._custom = (t.customNodes || []).length > 0;
    t._date = t.date || '';
    t._nodeTotal = Object.values(t.nodeTypes || {}).reduce((a, b) => a + b, 0);
    t._hayTitle = (t._title + ' ' + t.name).toLowerCase();
    t._hay = [
      t._title, t.name, t.description, t.category, t._out, t.username,
      ...(t.models || []), ...(t.tags || []), ...(t.customNodes || []),
      ...(t.modelFiles || []).map((m) => m.name), ...Object.keys(t.nodeTypes || {}),
    ].filter(Boolean).join('\n').toLowerCase();
    byName.set(t.name, t);
  }

  // ------------------------------------------------------------------ filtering

  const tokens = (q) => q.toLowerCase().split(/\s+/).filter(Boolean);

  function score(t, toks) {
    if (!toks.length) return 1;
    let s = 0;
    for (const k of toks) {
      if (!t._hay.includes(k)) return 0;
      s += t._hayTitle.includes(k) ? 10 : 1;
    }
    return s;
  }

  function passes(t, exceptKey) {
    for (const f of FACETS) {
      if (f.key === exceptKey) continue;
      const sel = state.sel[f.key];
      if (sel.size && !f.get(t).some((v) => sel.has(v))) return false;
    }
    return true;
  }

  function sortList(list, hasQuery) {
    const byIdx = (a, b) => a._i - b._i;
    const cmp = {
      default: hasQuery ? (a, b) => b._score - a._score || byIdx(a, b) : byIdx,
      newest: (a, b) => b._date.localeCompare(a._date) || byIdx(a, b),
      popular: (a, b) => (b.usage || 0) - (a.usage || 0) || byIdx(a, b),
      az: (a, b) => a._title.localeCompare(b._title),
      size: (a, b) => (a.size > 0 ? a.size : Infinity) - (b.size > 0 ? b.size : Infinity) || byIdx(a, b),
    }[state.sort] || byIdx;
    return list.sort((a, b) => {
      const r = cmp(a, b);
      return Number.isNaN(r) ? byIdx(a, b) : r;
    });
  }

  function compute() {
    const toks = tokens(state.q);
    const matched = [];
    for (const t of ALL) {
      const s = score(t, toks);
      if (s) { t._score = s; matched.push(t); }
    }
    const counts = {};
    for (const f of FACETS) {
      const c = new Map();
      for (const t of matched) {
        if (!passes(t, f.key)) continue;
        for (const v of new Set(f.get(t))) c.set(v, (c.get(v) || 0) + 1);
      }
      counts[f.key] = c;
    }
    return { results: sortList(matched.filter((t) => passes(t)), toks.length > 0), counts };
  }

  // ------------------------------------------------------------------ URL state

  function urlFor() {
    const p = new URLSearchParams();
    if (state.q) p.set('q', state.q);
    if (state.sort !== 'default') p.set('sort', state.sort);
    for (const f of FACETS) for (const v of state.sel[f.key]) p.append(f.key, v);
    const qs = p.toString();
    return location.pathname + (qs ? '?' + qs : '') + (state.open ? '#t=' + encodeURIComponent(state.open) : '');
  }

  function readURL() {
    const p = new URLSearchParams(location.search);
    state.q = p.get('q') || '';
    state.sort = SORTS.some(([k]) => k === p.get('sort')) ? p.get('sort') : 'default';
    for (const f of FACETS) state.sel[f.key] = new Set(p.getAll(f.key));
    const m = location.hash.match(/^#t=(.+)$/);
    const name = m ? decodeURIComponent(m[1]) : null;
    state.open = name && byName.has(name) ? name : null;
    $('#q').value = state.q;
    $('#sort').value = state.sort;
    lastSearch = location.search;
  }

  function writeURL() {
    history.replaceState(state.open ? history.state : null, '', urlFor());
    lastSearch = location.search;
  }

  // ------------------------------------------------------------------ facets

  function buildFacets() {
    const root = $('#facets');
    root.replaceChildren();
    for (const f of FACETS) {
      if (!f.values) {
        const seen = new Map();
        for (const t of ALL) for (const v of f.get(t)) if (v) seen.set(v, (seen.get(v) || 0) + 1);
        f.values = f.keepOrder
          ? [...seen.keys()]
          : [...seen.keys()].sort((a, b) => seen.get(b) - seen.get(a) || String(a).localeCompare(b));
      }
      const list = h('div', { class: 'facet-list' });
      const clear = h('button', {
        class: 'link-btn', type: 'button', hidden: true,
        onclick: () => { state.sel[f.key].clear(); update(true); },
      }, 'Clear');
      const search = f.searchable
        ? h('input', {
          class: 'facet-search', type: 'search', placeholder: `Find a ${f.label.toLowerCase()}…`,
          'aria-label': `Find ${f.label.toLowerCase()} options`,
          oninput: (e) => { state.facetQ[f.key] = e.target.value; renderFacetList(f); },
        })
        : null;
      f.el = { list, clear };
      root.append(h('section', { class: 'facet' }, h('div', { class: 'facet-head' }, h('h3', null, f.label), clear), search, list));
    }
  }

  function renderFacetList(f) {
    const counts = lastCounts[f.key] || new Map();
    const sel = state.sel[f.key];
    const fq = (state.facetQ[f.key] || '').trim().toLowerCase();
    let vals = f.values;
    if (fq) vals = vals.filter((v) => f.labelOf(v).toLowerCase().includes(fq));
    if (f.searchable) {
      vals = [...vals].sort((a, b) =>
        (sel.has(b) - sel.has(a)) || ((counts.get(b) || 0) - (counts.get(a) || 0)) || String(a).localeCompare(b));
    }
    const limit = f.limit && !state.expanded[f.key] && !fq ? Math.max(f.limit, sel.size) : Infinity;
    const groupOf = f.key === 'cat' ? (v) => catGroups.get(v) : null;
    const frag = document.createDocumentFragment();
    let lastGroup = null;
    for (const v of vals.slice(0, limit)) {
      if (groupOf) {
        const g = groupOf(v);
        if (g && g !== lastGroup) { frag.append(h('div', { class: 'facet-group' }, g)); lastGroup = g; }
      }
      const n = counts.get(v) || 0;
      const checked = sel.has(v);
      frag.append(h('label', { class: 'facet-opt' + (n || checked ? '' : ' is-empty') },
        h('input', {
          type: 'checkbox', checked,
          onchange: () => { if (checked) sel.delete(v); else sel.add(v); update(true); },
        }),
        h('span', { class: 'facet-name', title: f.labelOf(v) }, f.labelOf(v)),
        h('span', { class: 'facet-count' }, fmtNum(n))));
    }
    if (!vals.length) frag.append(h('p', { class: 'facet-none' }, 'No matches'));
    if (f.limit && !fq && vals.length > f.limit) {
      frag.append(h('button', {
        class: 'link-btn more', type: 'button',
        onclick: () => { state.expanded[f.key] = !state.expanded[f.key]; renderFacetList(f); },
      }, state.expanded[f.key] ? 'Show fewer' : `Show all ${vals.length}`));
    }
    f.el.list.replaceChildren(frag);
    f.el.clear.hidden = !sel.size;
  }

  let catGroups = new Map();

  // ------------------------------------------------------------------ toolbar

  function renderToolbar() {
    const total = ALL.length;
    const n = current.length;
    $('#count').replaceChildren(fmtNum(n), h('span', null, n === total ? ' templates' : ` of ${fmtNum(total)} templates`));

    const chips = [];
    const chip = (kind, text, onRemove) => h('button', {
      class: 'chip', type: 'button', title: `Remove ${kind}: ${text}`, onclick: onRemove,
    }, h('span', { class: 'chip-kind' }, kind), h('span', { class: 'chip-text' }, text), icon('x'));
    if (state.q) chips.push(chip('Search', `“${state.q}”`, () => { state.q = ''; $('#q').value = ''; update(true); }));
    let active = 0;
    for (const f of FACETS) {
      for (const v of state.sel[f.key]) {
        active++;
        chips.push(chip(f.label, f.labelOf(v), () => { state.sel[f.key].delete(v); update(true); }));
      }
    }
    if (chips.length > 1) chips.push(h('button', { class: 'link-btn', type: 'button', onclick: clearAll }, 'Clear all'));
    $('#chips').replaceChildren(...chips);

    const fc = $('#filter-count');
    fc.textContent = active;
    fc.hidden = !active;

    const def = $('#sort').querySelector('option[value="default"]');
    if (def) def.textContent = state.q ? 'Best match' : 'Featured';
  }

  function clearAll() {
    state.q = '';
    $('#q').value = '';
    for (const f of FACETS) state.sel[f.key].clear();
    update(true);
  }

  // ------------------------------------------------------------------ grid

  function placeholder(t, big) {
    return h('div', { class: 'ph ph-' + t._out + (big ? ' big' : '') }, icon(mediaIcon(t._out)));
  }

  function card(t) {
    const a = h('a', {
      class: 'card', href: '#t=' + encodeURIComponent(t.name),
      onclick: (e) => {
        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
        e.preventDefault();
        openDetail(t.name, true);
      },
    });
    const thumb = h('div', { class: 'thumb' });
    if (t._imgs[0]) {
      const img = h('img', { src: t._imgs[0], alt: '', loading: 'lazy', decoding: 'async' });
      img.addEventListener('error', () => img.replaceWith(placeholder(t)), { once: true });
      thumb.append(img);
      if (t._imgs[1]) {
        const alt = h('img', { class: 'thumb-alt', alt: '', decoding: 'async' });
        thumb.append(alt);
        a.addEventListener('mouseenter', () => { if (!alt.getAttribute('src')) alt.src = t._imgs[1]; }, { once: true });
      }
    } else {
      thumb.append(placeholder(t));
    }
    thumb.append(
      h('div', { class: 'badges' },
        t._api ? h('span', { class: 'badge badge-api', title: 'Uses API (cloud) nodes' }, 'API') : null,
        t._custom ? h('span', { class: 'badge badge-custom', title: 'Requires custom nodes: ' + t.customNodes.join(', ') }, 'Custom nodes') : null),
      h('span', { class: 'media-pill' }, icon(mediaIcon(t._out)), mediaLabel(t._out)));

    const models = t.models || [];
    a.append(thumb, h('div', { class: 'card-body' },
      h('h3', { class: 'card-title' }, t._title),
      t.description ? h('p', { class: 'card-desc' }, t.description) : null,
      h('p', { class: 'card-meta' }, [t.category, fmtDate(t.date)].filter(Boolean).join(' · ')),
      models.length ? h('div', { class: 'card-tags' },
        models.slice(0, 2).map((m) => h('span', { class: 'tag' }, m)),
        models.length > 2 ? h('span', { class: 'tag tag-more' }, '+' + (models.length - 2)) : null) : null));
    return a;
  }

  function renderMore() {
    const end = Math.min(current.length, shown + PAGE_SIZE);
    if (end <= shown) return;
    const frag = document.createDocumentFragment();
    for (let i = shown; i < end; i++) frag.append(card(current[i]));
    $('#grid').append(frag);
    shown = end;
  }

  function fillViewport() {
    const s = $('#sentinel');
    let guard = 0;
    while (shown < current.length && s.getBoundingClientRect().top < innerHeight + 900 && guard++ < 20) renderMore();
  }

  function renderGrid() {
    $('#grid').replaceChildren();
    shown = 0;
    renderMore();
    requestAnimationFrame(fillViewport);
    $('#empty').hidden = current.length > 0;
  }

  function skeleton() {
    const cards = Array.from({ length: 12 }, () => h('div', { class: 'card skeleton' },
      h('div', { class: 'thumb' }),
      h('div', { class: 'card-body' }, h('div', { class: 'sk-line', style: 'width:80%' }), h('div', { class: 'sk-line', style: 'width:55%' }))));
    $('#grid').replaceChildren(...cards);
  }

  // ------------------------------------------------------------------ update

  function update(fromUser) {
    const { results, counts } = compute();
    current = results;
    lastCounts = counts;
    for (const f of FACETS) renderFacetList(f);
    renderToolbar();
    renderGrid();
    writeURL();
    if (fromUser && scrollY > 0) scrollTo({ top: 0 });
  }

  // ------------------------------------------------------------------ detail

  const wfCache = new Map();

  function getWorkflow(t) {
    if (!t.workflowUrl) return Promise.reject(new Error('No workflow URL'));
    if (!wfCache.has(t.name)) {
      const p = fetch(t.workflowUrl).then((r) => {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.text();
      });
      p.catch(() => wfCache.delete(t.name));
      wfCache.set(t.name, p);
    }
    return wfCache.get(t.name);
  }

  async function downloadWorkflow(t) {
    try {
      const text = await getWorkflow(t);
      const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
      const a = h('a', { href: url, download: t.name + '.json' });
      document.body.append(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 4000);
      toast(`Saved ${t.name}.json — drop it onto the ComfyUI canvas to open it`);
    } catch {
      toast('Download failed — opening the raw file instead');
      window.open(t.workflowUrl, '_blank', 'noopener');
    }
  }

  async function copyWorkflow(t) {
    try {
      const text = await getWorkflow(t);
      await navigator.clipboard.writeText(text);
      toast('Workflow JSON copied — click the ComfyUI canvas and press Ctrl+V');
    } catch {
      toast('Could not copy to the clipboard');
    }
  }

  function upstreamBlob(t) {
    return SOURCE.repo ? `https://github.com/${SOURCE.repo}/blob/${SOURCE.ref || 'main'}/templates/${t.name}.json` : null;
  }

  const iconBtn = (name, label, fn) => h('button', {
    class: 'icon-btn', type: 'button', 'aria-label': label, title: label, disabled: !fn, onclick: fn || null,
  }, icon(name));

  const linkBtn = (ic, label, href) => (safeUrl(href)
    ? h('a', { class: 'btn', href, target: '_blank', rel: 'noopener' }, icon(ic), label)
    : null);

  function filterChips(values, key) {
    if (!values || !values.length) return null;
    return h('div', { class: 'row-tags' }, values.map((v) => h('button', {
      class: 'tag', type: 'button', title: `Show all templates with ${v}`,
      onclick: () => applyFilter(key, v),
    }, v)));
  }

  function applyFilter(key, value) {
    for (const f of FACETS) state.sel[f.key].clear();
    state.q = '';
    $('#q').value = '';
    state.sel[key].add(value);
    state.open = null;
    const dlg = $('#detail');
    if (dlg.open) dlg.close();
    document.title = BASE_TITLE;
    update(true);
  }

  function compareSlider(a, b, title) {
    const range = h('input', { type: 'range', min: '0', max: '100', value: '50', 'aria-label': 'Comparison position' });
    const wrap = h('div', { class: 'compare' },
      h('img', { src: b, alt: title + ' (after)' }),
      h('div', { class: 'compare-top' }, h('img', { src: a, alt: title + ' (before)' })),
      h('div', { class: 'compare-line' }),
      range);
    range.addEventListener('input', () => wrap.style.setProperty('--pos', range.value + '%'));
    return wrap;
  }

  function mediaBlock(t) {
    const imgs = t._imgs;
    const audio = t._audio.map((u) => h('audio', { controls: true, preload: 'none', src: u }));
    if (!imgs.length) return h('div', { class: 'd-media' }, placeholder(t, true), audio);
    if (t.thumbnailVariant === 'compareSlider' && imgs.length >= 2) {
      return h('div', { class: 'd-media' }, compareSlider(imgs[0], imgs[1], t._title), h('p', { class: 'hint' }, 'Drag across the image to compare'), audio);
    }
    const main = h('img', { src: imgs[0], alt: t._title });
    let strip = null;
    if (imgs.length > 1) {
      strip = h('div', { class: 'd-strip' }, imgs.map((u, k) => h('button', {
        class: 'd-thumb' + (k ? '' : ' is-active'), type: 'button', 'aria-label': `Preview ${k + 1}`,
        onclick: (e) => {
          main.src = u;
          strip.querySelectorAll('.d-thumb').forEach((b) => b.classList.toggle('is-active', b === e.currentTarget));
        },
      }, h('img', { src: u, alt: '', loading: 'lazy' }))));
    }
    return h('div', { class: 'd-media' }, h('div', { class: 'd-frame' }, main), strip, audio);
  }

  function section(title, sub, ...body) {
    return h('section', null, h('h3', null, title), sub ? h('p', { class: 'sub' }, sub) : null, ...body);
  }

  function renderDetail(t) {
    const list = current.includes(t) ? current : ALL;
    const i = list.indexOf(t);
    const prev = list[i - 1];
    const next = list[i + 1];

    const head = h('header', { class: 'd-head' },
      h('div', { class: 'd-titles' },
        h('p', { class: 'd-crumbs' }, [t.categoryGroup, t.category].filter(Boolean).join(' › ')),
        h('h2', { id: 'd-title', 'data-name': t.name }, t._title)),
      h('div', { class: 'd-nav' },
        h('span', { class: 'd-pos' }, `${fmtNum(i + 1)} / ${fmtNum(list.length)}`),
        iconBtn('chevL', 'Previous template (←)', prev ? () => openDetail(prev.name, false) : null),
        iconBtn('chevR', 'Next template (→)', next ? () => openDetail(next.name, false) : null),
        iconBtn('x', 'Close (Esc)', closeDetail)));

    const actions = h('div', { class: 'd-actions' },
      t.workflowUrl ? h('button', { class: 'btn btn-primary', type: 'button', onclick: () => downloadWorkflow(t) }, icon('download'), 'Download JSON') : null,
      t.workflowUrl ? h('button', { class: 'btn', type: 'button', onclick: () => copyWorkflow(t) }, icon('copy'), 'Copy JSON') : null,
      linkBtn('github', 'Source', upstreamBlob(t)),
      RELAY_REPO && t.page ? linkBtn('file', 'Markdown page', `https://github.com/${RELAY_REPO}/blob/main/${t.page}`) : null,
      linkBtn('book', 'Tutorial', t.tutorialUrl));

    const metaRows = [
      ['Models', filterChips(t.models, 'model')],
      ['Tags', filterChips(t.tags, 'tag')],
      ['Runs on', t._api ? 'API / cloud nodes (requires a Comfy account)' : 'Local — open-source models'],
      ['Output', mediaLabel(t._out)],
      ['Released', fmtDate(t.date)],
      ['Author', t.username],
      ['Download size', fmtSize(t.size)],
      ['Min. ComfyUI', t.minComfyUIVersion],
      ['Usage', fmtNum(t.usage)],
      ['Nodes', t._nodeTotal ? fmtNum(t._nodeTotal) : ''],
      ['Template ID', h('code', null, t.name)],
    ].filter(([, v]) => v != null && v !== '');
    const meta = h('dl', { class: 'd-meta' }, metaRows.map(([k, v]) => [h('dt', null, k), h('dd', null, v)]));

    const body = h('div', { class: 'd-body' },
      mediaBlock(t),
      h('div', { class: 'd-info' },
        t.description ? h('p', { class: 'd-desc' }, t.description) : null,
        actions,
        meta));

    const sections = h('div', { class: 'd-sections' });

    if (t.customNodes && t.customNodes.length) {
      sections.append(section('Custom nodes required', 'Install these with ComfyUI Manager or from the Comfy Registry before running.',
        h('div', { class: 'row-tags' }, t.customNodes.map((p) => h('a', {
          class: 'tag', href: `https://registry.comfy.org/nodes/${encodeURIComponent(p)}`, target: '_blank', rel: 'noopener',
        }, p, icon('external'))))));
    }

    if (t.modelFiles && t.modelFiles.length) {
      sections.append(section('Model files', 'Download each file into the listed folder inside ComfyUI/models/.',
        h('div', { class: 'table-wrap' }, h('table', { class: 'files' },
          h('thead', null, h('tr', null, h('th', null, 'File'), h('th', null, 'Folder'), h('th', null, ''))),
          h('tbody', null, t.modelFiles.map((m) => h('tr', null,
            h('td', null, h('code', null, m.name)),
            h('td', null, h('code', { class: 'muted' }, m.directory ? 'models/' + m.directory : '—')),
            h('td', { class: 'td-right' }, safeUrl(m.url)
              ? h('a', { class: 'btn btn-sm', href: m.url, target: '_blank', rel: 'noopener', title: m.url }, icon('download'), hostOf(m.url))
              : '—'))))))));
    }

    const io = t.io || {};
    const ioItems = [...(io.inputs || []).map((x) => ['in', x]), ...(io.outputs || []).map((x) => ['out', x])];
    if (ioItems.length) {
      sections.append(section('Inputs & outputs', null, h('ul', { class: 'io-list' }, ioItems.map(([dir, x]) => h('li', null,
        h('span', { class: 'io-dir' }, dir === 'in' ? 'Input' : 'Output'),
        h('code', null, x.nodeType || '?'),
        x.mediaType ? h('span', { class: 'tag' }, mediaLabel(x.mediaType)) : null,
        x.file ? h('span', { class: 'muted' }, x.file) : null)))));
    }

    const nodeTypes = Object.entries(t.nodeTypes || {}).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
    if (nodeTypes.length) {
      sections.append(h('section', null, h('details', { class: 'nodes' },
        h('summary', null, `Nodes used (${fmtNum(nodeTypes.length)} types, ${fmtNum(t._nodeTotal)} total)`),
        h('div', { class: 'row-tags' }, nodeTypes.map(([n, c]) => h('span', { class: 'tag node-chip' }, n, c > 1 ? h('b', null, '×' + c) : null))))));
    }

    const notesBox = h('div', null, h('p', { class: 'muted' }, 'Loading notes from the workflow…'));
    const notesSection = section('Notes from the workflow', null, notesBox);
    if (t.workflowUrl) sections.append(notesSection);

    const dlg = $('#detail');
    dlg.replaceChildren(head, h('div', { class: 'd-scroll' }, body, sections));
    if (t.workflowUrl) loadNotes(t, notesBox, notesSection);
  }

  function extractNotes(wf) {
    const nodes = [...(wf.nodes || [])];
    for (const sg of (wf.definitions && wf.definitions.subgraphs) || []) nodes.push(...(sg.nodes || []));
    return nodes
      .filter((n) => n && (n.type === 'Note' || n.type === 'MarkdownNote'))
      .map((n) => ({ type: n.type, title: n.title || n.type, text: String((n.widgets_values || [''])[0] || '').trim() }))
      .filter((n) => n.text);
  }

  function renderNote(n) {
    const div = h('div', { class: 'note-body' });
    if (n.type === 'MarkdownNote' && window.marked && window.DOMPurify) {
      div.innerHTML = window.DOMPurify.sanitize(window.marked.parse(n.text));
      div.querySelectorAll('a[href]').forEach((a) => { a.target = '_blank'; a.rel = 'noopener noreferrer'; });
    } else {
      div.classList.add('plain');
      div.textContent = n.text;
    }
    return div;
  }

  async function loadNotes(t, box, sec) {
    try {
      const notes = extractNotes(JSON.parse(await getWorkflow(t)));
      if (state.open !== t.name) return;
      if (!notes.length) { sec.remove(); return; }
      box.replaceChildren(...notes.map((n, k) => h('details', { class: 'note', open: k === 0 }, h('summary', null, n.title), renderNote(n))));
    } catch {
      if (state.open === t.name) box.replaceChildren(h('p', { class: 'muted' }, 'Could not load notes from the workflow file.'));
    }
  }

  function openDetail(name, push) {
    const t = byName.get(name);
    if (!t) return;
    state.open = name;
    if (push) history.pushState({ detail: true }, '', urlFor());
    else history.replaceState(history.state, '', urlFor());
    renderDetail(t);
    const dlg = $('#detail');
    if (!dlg.open) dlg.showModal();
    const scroller = dlg.querySelector('.d-scroll');
    if (scroller) scroller.scrollTop = 0;
    document.title = `${t._title} · ${BASE_TITLE}`;
  }

  function hideDetail() {
    state.open = null;
    const dlg = $('#detail');
    if (dlg.open) dlg.close();
    document.title = BASE_TITLE;
  }

  function closeDetail() {
    if (!state.open) return;
    if (history.state && history.state.detail) { history.back(); return; }
    hideDetail();
    history.replaceState(null, '', urlFor());
  }

  function syncDetailFromHash() {
    const m = location.hash.match(/^#t=(.+)$/);
    const name = m ? decodeURIComponent(m[1]) : null;
    if (name && byName.has(name)) {
      if (!$('#detail').open || $('#d-title')?.dataset.name !== name) openDetail(name, false);
    } else {
      hideDetail();
    }
  }

  // ------------------------------------------------------------------ theme

  const currentTheme = () => (document.documentElement.dataset.theme === 'light' ? 'light' : 'dark');

  function renderThemeButton() {
    const btn = $('#theme-btn');
    const dark = currentTheme() === 'dark';
    btn.replaceChildren(icon(dark ? 'sun' : 'moon'));
    btn.title = dark ? 'Switch to light theme' : 'Switch to dark theme';
    btn.setAttribute('aria-label', btn.title);
  }

  function toggleTheme() {
    const next = currentTheme() === 'dark' ? 'light' : 'dark';
    if (next === 'dark') delete document.documentElement.dataset.theme;
    else document.documentElement.dataset.theme = 'light';
    try { localStorage.setItem('theme', next); } catch { /* storage unavailable */ }
    document.querySelector('meta[name="theme-color"]')?.setAttribute('content', next === 'dark' ? '#0d0f0d' : '#c9d5c5');
    renderThemeButton();
  }

  // ------------------------------------------------------------------ wiring

  function setFiltersOpen(open) {
    document.body.classList.toggle('filters-open', open);
  }

  function bind() {
    $('#brand-mark').append(icon('logo'));
    $('#search-icon').innerHTML = ICONS.search;
    $('#filter-icon').innerHTML = ICONS.filter;
    $('#close-filters').append(icon('x'));
    const repo = $('#repo-link');
    repo.append(icon('github'));
    if (RELAY_REPO) repo.href = `https://github.com/${RELAY_REPO}`;
    else repo.hidden = true;
    renderThemeButton();
    $('#theme-btn').addEventListener('click', toggleTheme);

    $('#sort').append(...SORTS.map(([v, label]) => h('option', { value: v }, label)));
    $('#sort').addEventListener('change', (e) => { state.sort = e.target.value; update(true); });

    let qTimer;
    $('#q').addEventListener('input', (e) => {
      clearTimeout(qTimer);
      qTimer = setTimeout(() => { state.q = e.target.value.trim(); update(true); }, 140);
    });
    $('#q').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { clearTimeout(qTimer); state.q = e.target.value.trim(); update(true); }
    });

    $('#open-filters').addEventListener('click', () => setFiltersOpen(true));
    $('#close-filters').addEventListener('click', () => setFiltersOpen(false));
    $('#scrim').addEventListener('click', () => setFiltersOpen(false));
    $('#empty-clear').addEventListener('click', clearAll);

    const dlg = $('#detail');
    dlg.addEventListener('cancel', (e) => { e.preventDefault(); closeDetail(); });
    dlg.addEventListener('click', (e) => { if (e.target === dlg) closeDetail(); });

    document.addEventListener('keydown', (e) => {
      const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName) && document.activeElement.type !== 'range';
      if (dlg.open) {
        if (typing) return;
        if (e.key === 'ArrowLeft') dlg.querySelector('.d-nav button[aria-label^="Previous"]')?.click();
        if (e.key === 'ArrowRight') dlg.querySelector('.d-nav button[aria-label^="Next"]')?.click();
        return;
      }
      if (e.key === 'Escape' && document.body.classList.contains('filters-open')) setFiltersOpen(false);
      if (e.key === '/' && !typing) { e.preventDefault(); $('#q').focus(); $('#q').select(); }
    });

    new IntersectionObserver((entries) => {
      if (entries.some((en) => en.isIntersecting)) { renderMore(); requestAnimationFrame(fillViewport); }
    }, { rootMargin: '900px 0px' }).observe($('#sentinel'));

    window.addEventListener('popstate', () => {
      if (location.search !== lastSearch) { readURL(); update(false); }
      syncDetailFromHash();
    });
  }

  function renderSourceInfo() {
    const date = SOURCE.commitDate ? fmtDate(SOURCE.commitDate) : '';
    $('#subtitle').textContent = `${fmtNum(ALL.length)} workflow templates${date ? ' · updated ' + date : ''}`;
    const repoUrl = SOURCE.repo ? `https://github.com/${SOURCE.repo}` : null;
    const commit = SOURCE.commit ? SOURCE.commit.slice(0, 7) : '';
    $('#footer').replaceChildren(
      'Unofficial community browser. Workflows, previews and metadata come from ',
      repoUrl ? h('a', { href: repoUrl, target: '_blank', rel: 'noopener' }, SOURCE.repo) : 'the upstream repository',
      commit ? [' @ ', h('a', { href: `${repoUrl}/tree/${SOURCE.commit}/templates`, target: '_blank', rel: 'noopener' }, h('code', null, commit))] : null,
      date ? ` (${date})` : '', '. ',
      RELAY_REPO ? h('a', { href: `https://github.com/${RELAY_REPO}`, target: '_blank', rel: 'noopener' }, 'Markdown catalog & data') : null,
      RELAY_REPO ? '.' : null);
  }

  async function init() {
    bind();
    skeleton();
    let data;
    try {
      data = await loadData();
    } catch (e) {
      $('#grid').replaceChildren(h('div', { class: 'error' },
        h('h3', null, 'Could not load the template catalog'),
        h('p', null, String(e && e.message ? e.message : e))));
      $('#subtitle').textContent = 'Failed to load';
      return;
    }
    SOURCE = data.source || {};
    ALL = data.templates || [];
    ALL.forEach(prep);
    catGroups = new Map(ALL.map((t) => [t.category, t.categoryGroup]));
    renderSourceInfo();
    buildFacets();
    readURL();
    update(false);
    syncDetailFromHash();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
